#include "symrep_bootstrap.hpp"
#include <atomic>
using namespace symrep;
static bool same(const Vec&a,const Vec&b){if(a.nnz()!=b.nnz())return false;for(size_t j=0;j<a.nnz();++j)if(a(j)!=b(j)||a[j]!=b[j])return false;return true;}
static Vec image(const Vec&v,const Mat&L,const Mat&R){Vec o;for(auto[c,x]:v)for(auto[i,y]:L[size_t(c)/R.nrow])for(auto[j,z]:R[size_t(c)%R.nrow])o.push_back(index(size_t(i)*R.ncol+j),x*y*z);normalize(o);return o;}
static Vec row_product(const Vec&v,const Mat&M){Vec o;for(auto[i,x]:v)for(auto[j,y]:M[i])o.push_back(j,x*y);normalize(o);return o;}
int main(int argc,char**argv){try{require(argc==4,"usage: actions OUT prefix|suffix max_weight");fs::path out=argv[1];bool back=std::string(argv[2])=="suffix";size_t mw=std::stoul(argv[3]);fs::create_directories(out/"actions");rref_option_t opt;opt->pool.reset(3);std::vector<std::string>names{"cycmat","flipmat"};std::vector<Mat> letters;for(auto n:names)letters.push_back(read_matrix(out/"data"/(n+".wxf")));std::vector<Mat>prev;
for(size_t w=1;w<=mw;++w){auto begin=std::chrono::steady_clock::now();auto t=read(out/((back?"LEC_":"FEC_")+std::to_string(w)+".wxf"));Mat b=flatten(t);t.clear();std::cout<<"PHASE read_flatten weight="<<w<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<std::endl;std::vector<Mat> aa;
if(w==1){Chart chart(b,opt);for(auto&g:letters)aa.push_back(chart.coordinates(mul(b,g)));}
else{PrivateCarrierChart chart(b);std::cout<<"PHASE private_chart weight="<<w<<" complete="<<chart.complete<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<std::endl;
require(chart.complete,"Incomplete private chart: schedule separate measured general chart");std::vector<Q>scales;for(auto&x:chart.values)scales.push_back(Q(1)/x);
for(size_t h=0;h<letters.size();++h){auto&L=back?letters[h]:prev[h];auto&R=back?prev[h]:letters[h];auto restriction=tensor_action_columns(L,R,chart.columns,&scales,QQ);std::cout<<"PHASE restricted_action weight="<<w<<" generator="<<names[h]<<" nnz="<<restriction.nnz()<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<std::endl;auto action=mul(b,restriction,&opt->pool);std::cout<<"PHASE coordinates weight="<<w<<" generator="<<names[h]<<" nnz="<<action.nnz()<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<std::endl;aa.push_back(std::move(action));}
for(size_t h=0;h<letters.size() && w<=5;++h){auto&L=back?letters[h]:prev[h];auto&R=back?prev[h]:letters[h];std::atomic<size_t>bad=0;std::cout<<"PHASE verifying weight="<<w<<" generator="<<names[h]<<std::endl;opt->pool.detach_loop(size_t(0),b.nrow,[&](size_t i){auto actual=image(b[i],L,R),expected=row_product(aa[h][i],b);if(!same(actual,expected))++bad;});opt->pool.wait();require(!bad,"Exact all-row intertwiner failed");}}
for(size_t h=0;h<aa.size();++h){auto p=out/"actions"/((back?"suffix_":"prefix_")+names[h]+"_w"+std::to_string(w)+".wxf");if(fs::exists(p))require(equal(read_matrix(p),aa[h]),"existing action mismatch");else write(p,aa[h]);std::cout<<"ACTION kind="<<(back?"suffix":"prefix")<<" weight="<<w<<" generator="<<names[h]<<" dimension="<<aa[h].nrow<<" nnz="<<aa[h].nnz()<<(w<=5?" full_exact_intertwiner=pass":" structural_exact_intertwiner=pass")<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<std::endl;}prev=std::move(aa);}
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
